WITH flattened AS (SELECT id, coupon_codes, line.product_id, line.qty, line.price, line.promo FROM carts LATERAL VIEW EXPLODE(items) t AS line), flattened_carts AS (SELECT id, qty, price, promo, EXPLODE(coupon_codes) AS element FROM flattened), base AS (SELECT *, price + qty AS price_plus_qty FROM flattened_carts WHERE qty BETWEEN 3 AND 5), valid AS (SELECT *, CASE WHEN promo IN ('BUNDLE', 'VIP') THEN 'Group A' ELSE 'Other' END AS promo_group FROM base WHERE price_plus_qty < 35) SELECT id, price, price_plus_qty FROM valid;
